492	func IsPodReady(pod *k8sv1.Pod) bool {
493		if IsPodDownOrGoingDown(pod) {
494			return false
495		}
496	
497		for _, containerStatus := range pod.Status.ContainerStatuses {
498			// The compute container potentially holds a readiness probe for the VMI. Therefore
499			// don't wait for the compute container to become ready (the VMI later on will trigger the change to ready)
500			// and only check that the container started
501			if containerStatus.Name == "compute" {
502				if containerStatus.State.Running == nil {
503					return false
504				}
505			} else if containerStatus.Name == "istio-proxy" {
506				// When using istio the istio-proxy container will not be ready
507				// until there is a service pointing to this pod.
508				// We need to start the VM anyway
509				if containerStatus.State.Running == nil {
510					return false
511				}
512	
513			} else if containerStatus.Ready == false {
514				return false
515			}
516		}
517	
518		return pod.Status.Phase == k8sv1.PodRunning
519	}
