[metadata] {"filePath": "/workspace/repo/pkg/virt-controller/watch/vmi/lifecycle.go", "oldString": "func (c *Controller) addTopologyHints(vmi *virtv1.VirtualMachineInstance, vmiCopy *virtv1.VirtualMachineInstance) error {", "newString": "// migrationTargetShouldWaitForSync reports whether a decentralized migration target VMI
// can no longer make local progress and must therefore wait for a new synchronization.
// This is the case when its pod reached a terminal (Failed/Succeeded) state, or when the
// migration has already failed (Failed and Completed), even if the pod is still running.
func migrationTargetShouldWaitForSync(vmi *virtv1.VirtualMachineInstance, pod *k8sv1.Pod) bool {
	if !vmi.IsMigrationTarget() {
		return false
	}
	if pod != nil && controller.PodIsDown(pod) {
		return true
	}
	return vmi.Status.MigrationState != nil &&
		vmi.Status.MigrationState.Failed &&
		vmi.Status.MigrationState.Completed
}

